Write pipeline.py based on this spec:
This architecture follows a modular design pattern, ensuring that the core `Pipeline` class remains a clean orchestrator while specific domain logic is delegated to specialized "Engines." This separation of concerns allows for future expansion (e.g., adding an `AggregationEngine` or an `ExportEngine`) without modifying the `Pipeline` core.

### 1. `models.py`
Defines the core data contract for the system.

```python
from dataclasses import dataclass, field
from enum import Enum, auto
from typing import List, Optional, Any, Dict

class FieldType(Enum):
    STRING = auto()
    INTEGER = auto()
    FLOAT = auto()
    BOOLEAN = auto()

@dataclass
class Field:
    name: str
    field_type: FieldType
    nullable: bool = True
    default: Any = None

@dataclass
class Schema:
    name: str
    fields: List[Field]

@dataclass
class Record:
    data: Dict[str, Any]
    schema: Optional[Schema] = None

@dataclass
class ValidationResult:
    valid: bool
    errors: List[str] = field(default_factory=list)

class PipelineError(Exception):
    """Custom exception for pipeline-related failures."""
    pass
```

### 2. `pipeline.py`
The orchestrator. It uses `TransformEngine` and `SchemaValidator` to keep its logic focused on flow control.

```python
from typing import List, Callable, Tuple, Any
from models import Record, Schema, ValidationResult, PipelineError

class SchemaValidator:
    @staticmethod
    def validate(record: Record, schema: Schema) -> ValidationResult:
        """Validates record data against the provided schema."""
        errors = []
        for field in schema.fields:
            val = record.data.get(field.name, field.default)
            if not field.nullable and val is None:
                errors.append(f"Field {field.name} is non-nullable.")
            # Add type checking logic here later
        return ValidationResult(valid=len(errors) == 0, errors=errors)

class TransformEngine:
    @staticmethod
    def map_records(records: List[Record], func: Callable) -> List[Record]:
        return [Record(func(r.data), r.schema) for r in records]

    @staticmethod
    def filter_records(records: List[Record], predicate: Callable) -> List[Record]:
        return [r for r in records if predicate(r.data)]

    @staticmethod
    def sort_records(records: List[Record], key: str, reverse: bool = False) -> List[Record]:
        return sorted(records, key=lambda x: x.data.get(key), reverse=reverse)

class Pipeline:
    def __init__(self, name: str):
        self.name = name
        self.stages: List[Tuple[str, Callable]] = []
        self._audit_log: List[str] = []

    def add_stage(self, name: str, transform_fn: Callable[[List[Record]], List[Record]]):
        """Adds a processing stage to the pipeline."""
        self.stages.append((name, transform_fn))

    def execute(self, records: List[Record]) -> List[Record]:
        """Runs all stages in order and logs execution."""
        current_data = records
        for name, stage_fn in self.stages:
            try:
                current_data = stage_fn(current_data)
                self._audit_log.append(f"Stage '{name}' completed successfully.")
            except Exception as e:
                self._audit_log.append(f"Stage '{name}' failed: {str(e)}")
                raise PipelineError(f"Error in stage {name}: {e}")
        return current_data

    def validate(self, record: Record, schema: Schema) -> ValidationResult:
        return SchemaValidator.validate(record, schema)

    def get_audit_log(self) -> List[str]:
        return self._audit_log.copy()

    def clear_audit_log(self):
        self._audit_log = []
```

### 3. `test_pipeline.py`
Verifies core functionality and ensures the `Pipeline` behaves as expected.

```python
import pytest
from models import Record, Schema, Field, FieldType
from pipeline import Pipeline, TransformEngine, SchemaValidator

def test_pipeline_execution():
    p = Pipeline("TestPipe")
    records = [Record({"val": 1}), Record({"val": 2})]

    p.add_stage("increment", lambda rs: TransformEngine.map_records(rs, lambda d: {"val": d["val"] + 1}))
    results = p.execute(records)

    assert results[0].data["val"] == 2
    assert len(p.get_audit_log()) == 1

def test_schema_validator():
    schema = Schema("TestSchema", [Field("id", FieldType.INTEGER, nullable=False)])
    rec = Record({"id": None})
    res = SchemaValidator.validate(rec, schema)
    assert res.valid is False
    assert "id" in res.errors[0]

def test_audit_clear():
    p = Pipeline("TestPipe")
    p._audit_log.append("Log1")
    p.clear_audit_log()
    assert len(p.get_audit_log()) == 0

def test_transform_engine():
    records = [Record({"a": 1}), Record({"a": 2})]
    filtered = TransformEngine.filter_records(records, lambda d: d["a"] > 1)
    assert len(filtered) == 1
    assert filtered[0].data["a"] == 2
