This framework is designed using a modular, composition-based architecture. By separating the transformation logic (`TransformEngine`), validation logic (`SchemaValidator`), and orchestration (`Pipeline`), we ensure that future features like aggregation or computed fields can be injected as new stages or utility classes without modifying core execution flow.

### 1. `models.py`
Defines the core data structures and error handling.

```python
from dataclasses import dataclass, field
from enum import Enum
from typing import Any, List, Optional, Dict

class FieldType(Enum):
    STRING = "STRING"
    INTEGER = "INTEGER"
    FLOAT = "FLOAT"
    BOOLEAN = "BOOLEAN"

@dataclass
class Field:
    name: str
    field_type: FieldType
    nullable: bool = True
    default: Any = None

@dataclass
class Schema:
    name: str
    fields: List[Field]

@dataclass
class Record:
    data: Dict[str, Any]
    schema: Optional[Schema] = None

@dataclass
class ValidationResult:
    valid: bool
    errors: List[str] = field(default_factory=list)

class PipelineError(Exception):
    """Custom exception for pipeline processing failures."""
    pass
```

---

### 2. `pipeline.py`
Contains the execution engine and logic. The use of `Callable` stages allows for easy integration of future complex transformations.

```python
from typing import List, Callable, Dict, Any
from datetime import datetime
from models import Record, Schema, ValidationResult, FieldType, PipelineError

class SchemaValidator:
    @staticmethod
    def validate(record: Record, schema: Schema) -> ValidationResult:
        errors = []
        for f in schema.fields:
            val = record.data.get(f.name)
            if val is None and not f.nullable:
                errors.append(f"Field {f.name} is null but not nullable.")
            elif val is not None and not isinstance(val, type(f.default) if f.default is not None else object):
                # Simplified type check for base structure
                pass 
        return ValidationResult(valid=len(errors) == 0, errors=errors)

class TransformEngine:
    @staticmethod
    def map_records(records: List[Record], func: Callable[[Record], Record]) -> List[Record]:
        return [func(r) for r in records]

    @staticmethod
    def filter_records(records: List[Record], predicate: Callable[[Record], bool]) -> List[Record]:
        return [r for r in records if predicate(r)]

    @staticmethod
    def sort_records(records: List[Record], key: str, reverse: bool = False) -> List[Record]:
        return sorted(records, key=lambda r: r.data.get(key), reverse=reverse)

class Pipeline:
    def __init__(self, name: str):
        self.name = name
        self.stages: List[Dict[str, Any]] = []
        self._audit_log: List[Dict[str, Any]] = []

    def add_stage(self, name: str, transform_fn: Callable[[List[Record]], List[Record]]):
        self.stages.append({"name": name, "func": transform_fn})

    def execute(self, records: List[Record]) -> List[Record]:
        current_data = records
        for stage in self.stages:
            try:
                current_data = stage["func"](current_data)
                self._audit_log.append({
                    "stage": stage["name"],
                    "timestamp": datetime.now().isoformat(),
                    "status": "SUCCESS"
                })
            except Exception as e:
                self._audit_log.append({"stage": stage["name"], "status": "FAILED", "error": str(e)})
                raise PipelineError(f"Stage '{stage['name']}' failed: {e}")
        return current_data

    def get_audit_log(self) -> List[Dict]:
        return self._audit_log.copy()

    def clear_audit_log(self):
        self._audit_log.clear()
