def test_schema_validator():
    schema = Schema("Test", [Field("id", FieldType.INTEGER, nullable=False)])
    rec_valid = Record({"id": 1})
    rec_invalid = Record({"id": None})

    assert SchemaValidator.validate(rec_valid, schema).valid is True
    assert SchemaValidator.validate(rec_invalid, schema).valid is False

def test_pipeline_execution():
    pipe = Pipeline("TestPipeline")
    pipe.add_stage("double_id", lambda recs: [Record({**r.data, "id": r.data["id"] * 2}) for r in recs])

